+        SavedConversation out = std::move(entries_.at(index));
+        // bytes_ was accumulated from image.bytes() at put(); subtract the same accounting the
+        // entry was inserted with, not a re-derivation from the moved-from object.
+        bytes_ -= out.bytes();   // out is still the moved-INTO object; entries_.at(index) is the moved-FROM one
